// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.IdentityRESTToken) predicate.IdentityRESTToken {
	return predicate.IdentityRESTToken(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.IdentityRESTToken) predicate.IdentityRESTToken {
	return predicate.IdentityRESTToken(sql.NotPredicates(p))
}
